DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `rebuild_leaderboards` ()   BEGIN   
    DECLARE current_season INT;   
    SELECT id INTO current_season FROM seasons WHERE is_current = 1 LIMIT 1;     

    -- Clear existing   
    DELETE FROM leaderboards WHERE season_id = current_season;     

    -- Points   
    SELECT current_season, ps.player_id, 'points', ps.points_per_game,            
           RANK() OVER (ORDER BY ps.points_per_game DESC)   
    FROM player_stats ps   
    JOIN players p ON ps.player_id = p.id   
    WHERE ps.season_id = current_season      
      AND ps.points_per_game > 0   
      AND ps.games_played >= 15 
      AND p.is_active = 1   
    ORDER BY ps.points_per_game DESC   
    LIMIT 10;     

    -- Rebounds   
    SELECT current_season, ps.player_id, 'rebounds', ps.rebounds_per_game,            
           RANK() OVER (ORDER BY ps.rebounds_per_game DESC)   
    FROM player_stats ps   
    JOIN players p ON ps.player_id = p.id   
    WHERE ps.season_id = current_season      
      AND ps.rebounds_per_game > 0    
      AND ps.games_played >= 15   
      AND p.is_active = 1   
    ORDER BY ps.rebounds_per_game DESC   
    LIMIT 10;     

    -- Assists   
    SELECT current_season, ps.player_id, 'assists', ps.assists_per_game,            
           RANK() OVER (ORDER BY ps.assists_per_game DESC)   
    FROM player_stats ps   
    JOIN players p ON ps.player_id = p.id   
    WHERE ps.season_id = current_season      
      AND ps.assists_per_game > 0      
      AND ps.games_played >= 15
      AND p.is_active = 1   
    ORDER BY ps.assists_per_game DESC   
    LIMIT 10;     

    -- Steals   
    SELECT current_season, ps.player_id, 'steals', ps.steals_per_game,            
           RANK() OVER (ORDER BY ps.steals_per_game DESC)   
    FROM player_stats ps   
    JOIN players p ON ps.player_id = p.id   
    WHERE ps.season_id = current_season      
      AND ps.steals_per_game > 0      
      AND ps.games_played >= 15
      AND p.is_active = 1   
    ORDER BY ps.steals_per_game DESC   
    LIMIT 10;     

    -- Blocks   
    SELECT current_season, ps.player_id, 'blocks', ps.blocks_per_game,            
           RANK() OVER (ORDER BY ps.blocks_per_game DESC)   
    FROM player_stats ps   
    JOIN players p ON ps.player_id = p.id   
    WHERE ps.season_id = current_season      
      AND ps.blocks_per_game > 0      
      AND ps.games_played >= 15
      AND p.is_active = 1   
    ORDER BY ps.blocks_per_game DESC   
    LIMIT 10;     

    -- Field Goal Efficiency (Min 15 PPG & 15 Games Played)
    SELECT current_season, ps.player_id, 'three_pt', -- Keeping category name as 'three_pt' so your JS frontend doesn't break!
           ps.field_goal_pct,            
           RANK() OVER (ORDER BY ps.field_goal_pct DESC)   
    FROM player_stats ps   
    JOIN players p ON ps.player_id = p.id   
    WHERE ps.season_id = current_season      
      AND ps.field_goal_pct > 0   
      AND ps.games_played >= 15
      AND ps.points_per_game >= 15 -- The volume qualifier!
      AND p.is_active = 1   
    ORDER BY ps.field_goal_pct DESC   
    LIMIT 10;     

    SELECT 'Leaderboards rebuilt successfully' AS result;
END$$

DELIMITER ;

