INSERT INTO `history_timeline` (`id`, `event_year`, `title`, `description`, `category`, `image_url`, `related_team_id`, `related_player`, `sort_order`) VALUES
(21, '1946', 'The NBA Begins', 'The Basketball Association of America launches, later becoming the NBA.', 'league', NULL, NULL, NULL, 1),
(22, '1979', 'Three-Point Line Added', 'The NBA adopts the three-point line and changes spacing forever.', 'rules', NULL, NULL, NULL, 2),
(23, '1984', 'Michael Jordan Drafted', 'Chicago drafts Michael Jordan, starting one of the most famous careers in sports.', 'legend', NULL, NULL, NULL, 3),
(24, '1992', 'The Dream Team', 'NBA stars dominate the Olympics and help basketball explode globally.', 'global', NULL, NULL, NULL, 4),
(25, '1996', 'The 72-Win Bulls', 'Chicago finishes 72-10 and wins another championship behind Jordan and Pippen.', 'dynasty', NULL, NULL, NULL, 5),
(26, '2015', 'Warriors Start a Shooting Era', 'Golden State wins the title and pushes the league toward pace and threes.', 'modern', NULL, NULL, NULL, 6),
(27, '2021', 'Giannis Wins Milwaukee a Title', 'Giannis Antetokounmpo leads the Bucks to their first championship in 50 years.', 'championship', NULL, NULL, NULL, 7),
(28, '2023', 'Denver Wins Its First Title', 'Nikola Jokic leads the Nuggets to their first NBA championship.', 'championship', NULL, NULL, NULL, 8),
(29, '2024', 'Boston Captures Banner 18', 'The Celtics reclaim the top spot in NBA championship history.', 'championship', NULL, NULL, NULL, 9),
(30, '2025', 'Global Stars Lead the League', 'International stars define the modern NBA spotlight.', 'global', NULL, NULL, NULL, 10);
